'use client';

import React, { useState, useRef, useEffect } from 'react';
import {
    DndContext,
    DragOverlay,
    DragStartEvent,
    DragEndEvent,
    MouseSensor,
    TouchSensor,
    useSensor,
    useSensors,
    pointerWithin,
    CollisionDetection,
    rectIntersection,
} from '@dnd-kit/core';
import { createPortal } from 'react-dom';
import { Package, Layout, Copy, Trash2 } from 'lucide-react'; // Combined imports for lucide-react

import { PropositionType, Proposition, Vendor, Product, Solution, CanvasItem } from '@/lib/types';
import { CanvasSidebar } from '../CanvasSidebar';
import { CanvasWorkspace } from '../CanvasWorkspace';
import { PropertiesPanel } from '../PropertiesPanel';
import { useMultiSelect } from '@/hooks/useMultiSelect';
import { useKeyboardShortcuts } from '@/hooks/useKeyboardShortcuts';
import { useModifierKeys } from '@/hooks/useModifierKeys';
import { ContextMenu, ContextMenuAction } from '../controls/ContextMenu';
import { Layers, AlignLeft, Grid } from 'lucide-react'; // Remaining lucide-react imports

// Custom collision strategy
const customCollisionStrategy: CollisionDetection = (args) => {
    const pointerCollisions = pointerWithin(args);
    if (pointerCollisions.length > 0) return pointerCollisions;
    const rectCollisions = rectIntersection(args);
    return rectCollisions.filter(c => c.id === 'canvas-droppable');
};

// Mock Data
const PROPOSITIONS: Proposition[] = [
    { id: 'digital-workspace', label: 'Digital Workspace' },
    { id: 'hybrid-cloud', label: 'Hybrid Cloud' },
    { id: 'artificial-intelligence', label: 'AI' },
    { id: 'cloud-native', label: 'Cloud Native' },
];

const VENDORS: Vendor[] = [
    { id: 'v-vmware', name: 'VMware' },
    { id: 'v-microsoft', name: 'Microsoft' },
    { id: 'v-aws', name: 'AWS' },
    { id: 'v-google', name: 'Google Cloud' },
];

const PRODUCTS: Product[] = [
    { id: 'p-vsphere', vendorId: 'v-vmware', propositionId: 'hybrid-cloud', name: 'vSphere' },
    { id: 'p-horizon', vendorId: 'v-vmware', propositionId: 'digital-workspace', name: 'Horizon' },
    { id: 'p-azure-vd', vendorId: 'v-microsoft', propositionId: 'digital-workspace', name: 'Azure Virtual Desktop' },
    { id: 'p-m365', vendorId: 'v-microsoft', propositionId: 'digital-workspace', name: 'Microsoft 365' },
    { id: 'p-openai', vendorId: 'v-microsoft', propositionId: 'artificial-intelligence', name: 'Azure OpenAI' },
    { id: 'p-eks', vendorId: 'v-aws', propositionId: 'cloud-native', name: 'Amazon EKS' },
];

const SOLUTIONS: Solution[] = [
    { id: 's-hybrid-workspace', name: 'Modern Hybrid Workspace', productIds: ['p-horizon', 'p-m365'] },
];

export function CanvasBoard() {
    // State
    const [items, setItems] = useState<CanvasItem[]>([]);
    const [activeDragData, setActiveDragData] = useState<any>(null);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedProposition, setSelectedProposition] = useState<PropositionType | 'all'>('all');
    const [mounted, setMounted] = useState(false);
    const [debugInfo, setDebugInfo] = useState<string>('Ready');

    const canvasRef = useRef<HTMLDivElement>(null);

    // Context Menu State
    const [contextMenu, setContextMenu] = useState<{ x: number, y: number, visible: boolean }>({ x: 0, y: 0, visible: false });

    // Multi-select hook
    const multiSelect = useMultiSelect();

    // Modifier keys
    const keys = useModifierKeys();

    useEffect(() => {
        setMounted(true);
    }, []);

    // Keyboard shortcuts
    useKeyboardShortcuts({
        onSelectAll: () => multiSelect.selectAll(items.map(i => i.id)),
        onDelete: () => {
            const selected = multiSelect.selectedIds;
            if (selected.length > 0) {
                setItems(prev => prev.filter(item => !selected.includes(item.id)));
                multiSelect.clearSelection();
                setDebugInfo(`Deleted ${selected.length} item(s)`);
            }
        },
        onDuplicate: () => {
            const selected = multiSelect.selectedIds;
            if (selected.length > 0) {
                const newItems = items
                    .filter(item => selected.includes(item.id))
                    .map(item => ({
                        ...item,
                        id: `item-${Date.now()}-${Math.random()}`,
                        x: item.x + 20,
                        y: item.y + 20
                    }));
                setItems(prev => [...prev, ...newItems]);
                setDebugInfo(`Duplicated ${selected.length} item(s)`);
            }
        },
        onEscape: () => multiSelect.clearSelection(),
        onNudgeUp: () => {
            const selected = multiSelect.selectedIds;
            if (selected.length > 0) {
                setItems(prev => prev.map(item =>
                    selected.includes(item.id) ? { ...item, y: item.y - 1 } : item
                ));
            }
        },
        onNudgeDown: () => {
            const selected = multiSelect.selectedIds;
            if (selected.length > 0) {
                setItems(prev => prev.map(item =>
                    selected.includes(item.id) ? { ...item, y: item.y + 1 } : item
                ));
            }
        },
        onNudgeLeft: () => {
            const selected = multiSelect.selectedIds;
            if (selected.length > 0) {
                setItems(prev => prev.map(item =>
                    selected.includes(item.id) ? { ...item, x: item.x - 1 } : item
                ));
            }
        },
        onNudgeRight: () => {
            const selected = multiSelect.selectedIds;
            if (selected.length > 0) {
                setItems(prev => prev.map(item =>
                    selected.includes(item.id) ? { ...item, x: item.x + 1 } : item
                ));
            }
        },
    }, mounted);

    const sensors = useSensors(
        useSensor(MouseSensor, { activationConstraint: { distance: 5 } }),
        useSensor(TouchSensor, { activationConstraint: { delay: 250, tolerance: 5 } })
    );

    // Prevent hydration mismatch
    if (!mounted) return (
        <div className="h-screen w-full bg-gray-950 flex items-center justify-center">
            <div className="w-8 h-8 rounded-full border-2 border-blue-500 border-t-transparent animate-spin" />
        </div>
    );

    // Handlers
    const handleDragStart = (event: DragStartEvent) => {
        setActiveDragData(event.active.data.current);
        setDebugInfo(`Dragging ${event.active.data.current?.label}...`);
    };

    const handleDragEnd = (event: DragEndEvent) => {
        const { active, over } = event;
        setActiveDragData(null);

        if (!over || over.id !== 'canvas-droppable') {
            setDebugInfo('Dropped outside canvas');
            return;
        }

        const canvasRect = canvasRef.current?.getBoundingClientRect();
        const sourceData = active.data.current;
        if (!sourceData) return;

        const droppedRect = active.rect.current.translated;
        const rawX = droppedRect ? (droppedRect.left - (canvasRect?.left ?? 0)) : 100;
        const rawY = droppedRect ? (droppedRect.top - (canvasRect?.top ?? 0)) : 100;

        if (sourceData.source === 'sidebar') {
            const newItem: CanvasItem = {
                id: `item-${Date.now()}`,
                entityId: sourceData.entityId,
                entityType: sourceData.type,
                x: rawX,
                y: rawY,
                data: sourceData
            };
            setItems(prev => [...prev, newItem]);
            multiSelect.selectMultiple([newItem.id]);
            setDebugInfo(`Added ${newItem.data.label}`);
        } else if (sourceData.source === 'canvas') {
            const isCopying = keys.ctrl || keys.alt;

            if (isCopying) {
                const newItemId = `item-${Date.now()}-${Math.random()}`;

                setItems(prev => {
                    const original = prev.find(it => it.id === active.id);
                    if (!original) return prev;

                    const newItem = {
                        ...original,
                        id: newItemId,
                        x: rawX,
                        y: rawY
                    };
                    return [...prev, newItem];
                });

                multiSelect.selectMultiple([newItemId]);
                setDebugInfo(`Copied item`);
            } else {
                setItems(prev => prev.map(it => {
                    if (it.id === active.id) {
                        return {
                            ...it,
                            x: rawX,
                            y: rawY
                        };
                    }
                    return it;
                }));
                setDebugInfo(`Moved item`);
            }
        }
    };

    // Context Menu Actions
    const handleContextMenu = (e: React.MouseEvent) => {
        e.preventDefault();
        setContextMenu({ x: e.clientX, y: e.clientY, visible: true });
    };

    const contextMenuActions: ContextMenuAction[] = [
        {
            id: 'duplicate',
            label: 'Duplicate',
            icon: <Copy className="w-4 h-4" />,
            action: () => {
                const selected = multiSelect.selectedIds;
                if (selected.length > 0) {
                    const newItems = items
                        .filter(item => selected.includes(item.id))
                        .map(item => ({
                            ...item,
                            id: `item-${Date.now()}-${Math.random()}`,
                            x: item.x + 20,
                            y: item.y + 20
                        }));
                    setItems(prev => [...prev, ...newItems]);
                    setDebugInfo(`Duplicated ${selected.length} item(s)`);
                }
            },
            shortcut: 'Ctrl+D'
        },
        {
            id: 'delete',
            label: 'Delete',
            icon: <Trash2 className="w-4 h-4" />,
            action: () => {
                const selected = multiSelect.selectedIds;
                if (selected.length > 0) {
                    setItems(prev => prev.filter(item => !selected.includes(item.id)));
                    multiSelect.clearSelection();
                }
            },
            shortcut: 'Del',
            danger: true
        }
    ];

    // Filters
    const filteredProducts = PRODUCTS.filter(p => {
        const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesProp = selectedProposition === 'all' || p.propositionId === selectedProposition;
        return matchesSearch && matchesProp;
    });

    const selectedItem = multiSelect.selectedIds.length === 1
        ? items.find(it => it.id === multiSelect.selectedIds[0])
        : undefined;
    const getVendorName = (vendorId: string) => VENDORS.find(v => v.id === vendorId)?.name;

    return (
        <DndContext
            id="qanvas-dnd-root"
            sensors={sensors}
            onDragStart={handleDragStart}
            onDragEnd={handleDragEnd}
            collisionDetection={customCollisionStrategy}
        >
            <div
                className="flex h-screen w-full overflow-hidden bg-[hsl(var(--background))] text-[hsl(var(--foreground))]"
                onContextMenu={handleContextMenu}
            >
                <CanvasSidebar
                    searchQuery={searchQuery}
                    onSearchChange={setSearchQuery}
                    selectedProposition={selectedProposition}
                    onPropositionChange={setSelectedProposition}
                    propositions={PROPOSITIONS}
                    filteredProducts={filteredProducts}
                    solutions={SOLUTIONS}
                    vendors={VENDORS}
                    getVendorName={getVendorName}
                />

                <CanvasWorkspace
                    canvasRef={canvasRef}
                    items={items}
                    selectedIds={multiSelect.selectedIds}
                    debugInfo={debugInfo}
                    vendors={VENDORS}
                    multiSelect={multiSelect}
                    onClearItems={() => {
                        setItems([]);
                        multiSelect.clearSelection();
                    }}
                />

                {contextMenu.visible && (
                    <ContextMenu
                        x={contextMenu.x}
                        y={contextMenu.y}
                        onClose={() => setContextMenu({ ...contextMenu, visible: false })}
                        actions={contextMenuActions}
                        selectedCount={multiSelect.selectedIds.length}
                    />
                )}

                <PropertiesPanel
                    selectedItem={selectedItem}
                    selectedCount={multiSelect.selectedCount}
                    propositions={PROPOSITIONS}
                    vendors={VENDORS}
                />
            </div>

            {mounted && createPortal(
                <DragOverlay dropAnimation={null}>
                    {activeDragData ? (
                        <div className="p-4 w-60 rounded-2xl border border-blue-500 bg-gray-900 shadow-2xl scale-105 opacity-90 z-[100] cursor-grabbing pointer-events-none">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-blue-500/20 text-blue-400 flex items-center justify-center">
                                    {activeDragData.type === 'product' ? <Package className="w-5 h-5" /> : <Layout className="w-5 h-5" />}
                                </div>
                                <div className="flex flex-col">
                                    <span className="text-sm font-bold text-white">{activeDragData.label}</span>
                                    <span className="text-[10px] text-white/40 uppercase tracking-widest">Dropping...</span>
                                </div>
                            </div>
                        </div>
                    ) : null}
                </DragOverlay>,
                document.body
            )}
        </DndContext>
    );
}
